using System;
using Astrea.BattleActions;
using LittleLeo;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnNewRuneOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnNewRune Omen Data")]
public class OnNewRuneOmenData : OmenData
{
	private const string replaceSpecificVirtueID = "ReplaceSpecificVirtue";

	private const string replaceAllVirtuesID = "ReplaceAllVirtues";

	private const string receiveVirtueID = "ReceiveVirtue";

	private const string loseSpecificVirtueID = "LoseSpecificVirtue";

	private const string replaceVirtueID = "ReplaceVirtue";

	private const string leftmostID = "Leftmost";

	private const string rightmostID = "Rightmost";

	[Header("On New Rune Omen")]
	[SerializeField]
	protected GameObjectReference runesPanelGameObjectReference;

	[SerializeField]
	private NewRuneType newRuneType;

	[SerializeField]
	[HideIf("ReplaceAllRunes")]
	private bool mostRight;

	[SerializeField]
	[ShowIf("AddRune")]
	private bool loseRune;

	[SerializeField]
	[ShowIf("replaceSpecificRuneOrAddRuneAndLoseRune")]
	private BattleAction specificRuneBattleAction;

	[SerializeField]
	[ShowIf("replaceSpecificRuneOrAddRuneAndLoseRune")]
	private bool enableSpecificRuneActionValue;

	[SerializeField]
	[ShowIf("enableSpecificRuneActionValue")]
	private int specificRuneActionValue;

	[SerializeField]
	private bool enableSecondVirtueChange;

	[SerializeField]
	[ShowIf("enableSecondVirtueChange")]
	private OnNewRuneOmenData secondVirtueChange;

	[SerializeField]
	private bool isSecondVirtueChange;

	[NonSerialized]
	private Rune oldRune;

	[NonSerialized]
	private Rune[] oldRunes;

	[NonSerialized]
	private Rune oldRuneLoseRune;

	public bool AddRune => newRuneType == NewRuneType.AddRune;

	public bool LoseRune => loseRune;

	private bool replaceSpecificRuneOrAddRuneAndLoseRune
	{
		get
		{
			if (newRuneType != NewRuneType.ReplaceSpecificRune)
			{
				if (AddRune)
				{
					return loseRune;
				}
				return false;
			}
			return true;
		}
	}

	public bool ReplaceAllRunes => newRuneType == NewRuneType.ReplaceAllRunes;

	public override void Initialize(OmenInstance omenInstance)
	{
		RunesPanelInitializer component = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>();
		component.ResetRunesToNonShuffledRunes();
		if (newRuneType == NewRuneType.AddRune)
		{
			if (loseRune)
			{
				int specificRuneIndex = GetSpecificRuneIndex();
				if (specificRuneIndex != -1)
				{
					Rune rune = component.Runes[specificRuneIndex];
					oldRuneLoseRune = new Rune(rune.FaceName, rune.ActionValue, rune.BattleAction, rune.index);
					component.ReplaceRuneWithNewRune(null, 0, specificRuneIndex);
				}
			}
			int emptyIndex = GetEmptyIndex();
			if (emptyIndex != -1)
			{
				SetOldRune(component.Runes[emptyIndex]);
				oldRune.index = emptyIndex;
				component.AddNewRune(BattleAction, ActionValue, emptyIndex);
			}
		}
		else if (newRuneType == NewRuneType.ReplaceSpecificRune)
		{
			int specificRuneIndex2 = GetSpecificRuneIndex();
			if (specificRuneIndex2 != -1)
			{
				SetOldRune(component.Runes[specificRuneIndex2], BattleAction);
				component.ReplaceRuneWithNewRune(BattleAction, ActionValue, specificRuneIndex2);
			}
		}
		else if (newRuneType == NewRuneType.ReplaceRune)
		{
			int nonEmptyIndex = GetNonEmptyIndex();
			if (nonEmptyIndex != -1)
			{
				SetOldRune(component.Runes[nonEmptyIndex], BattleAction);
				component.ReplaceRuneWithNewRune(BattleAction, ActionValue, nonEmptyIndex);
			}
		}
		else if (newRuneType == NewRuneType.ReplaceAllRunes)
		{
			oldRunes = new Rune[component.Runes.Length];
			for (int i = 0; i < oldRunes.Length; i++)
			{
				Rune rune2 = component.Runes[i];
				oldRunes[i] = new Rune(rune2.FaceName, rune2.ActionValue, rune2.BattleAction, rune2.index);
				if (rune2.BattleAction != null)
				{
					component.ReplaceRuneWithNewRune(BattleAction, ActionValue, i);
				}
			}
		}
		if (enableSecondVirtueChange)
		{
			secondVirtueChange.Initialize(omenInstance);
		}
		if (!isSecondVirtueChange)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 5, delegate
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
			});
		}
	}

	private void SetOldRune(Rune rune, BattleAction ReplacedBattleAction = null)
	{
		oldRune = new Rune(rune.FaceName, rune.ActionValue, rune.BattleAction, rune.index, ReplacedBattleAction);
	}

	public override void OmenRemoved()
	{
		RunesPanelInitializer component = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>();
		component.ResetRunesToNonShuffledRunes();
		if (ReplaceAllRunes)
		{
			for (int i = 0; i < oldRunes.Length; i++)
			{
				component.GoBackToOldRune(oldRunes[i]);
			}
		}
		else
		{
			if ((bool)oldRune.ReplacedBattleAction)
			{
				Rune[] runes = component.Runes;
				for (int j = 0; j < runes.Length; j++)
				{
					if (runes[j].BattleAction == oldRune.ReplacedBattleAction)
					{
						oldRune.index = j;
					}
				}
			}
			component.GoBackToOldRune(oldRune);
		}
		if (AddRune && loseRune)
		{
			component.GoBackToOldRune(oldRuneLoseRune);
		}
		if (enableSecondVirtueChange)
		{
			secondVirtueChange.OmenRemoved();
		}
	}

	public int GetEmptyIndex()
	{
		Rune[] runes = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>().Runes;
		if (!mostRight)
		{
			for (int num = runes.Length - 1; num >= 0; num--)
			{
				if (runes[num].BattleAction == null)
				{
					return num;
				}
			}
		}
		else
		{
			for (int i = 0; i < runes.Length; i++)
			{
				if (runes[i].BattleAction == null)
				{
					return i;
				}
			}
		}
		return -1;
	}

	public int GetSpecificRuneIndex()
	{
		Rune[] runes = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>().Runes;
		if (!mostRight)
		{
			for (int num = runes.Length - 1; num >= 0; num--)
			{
				if (runes[num].BattleAction == specificRuneBattleAction)
				{
					if (!enableSpecificRuneActionValue)
					{
						return num;
					}
					if (runes[num].ActionValue == specificRuneActionValue)
					{
						return num;
					}
				}
			}
		}
		else
		{
			for (int i = 0; i < runes.Length; i++)
			{
				if (runes[i].BattleAction == specificRuneBattleAction)
				{
					if (!enableSpecificRuneActionValue)
					{
						return i;
					}
					if (runes[i].ActionValue == specificRuneActionValue)
					{
						return i;
					}
				}
			}
		}
		return -1;
	}

	public int GetNonEmptyIndex()
	{
		Rune[] runes = runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>().Runes;
		if (!mostRight)
		{
			for (int num = runes.Length - 1; num >= 0; num--)
			{
				if (runes[num].BattleAction != null)
				{
					return num;
				}
			}
		}
		else
		{
			for (int i = 0; i < runes.Length; i++)
			{
				if (runes[i].BattleAction != null)
				{
					return i;
				}
			}
		}
		return -1;
	}

	public override string OmenConvertedDescription()
	{
		if (newRuneType == NewRuneType.AddRune)
		{
			string localizedString = GetLocalizedString("ReceiveVirtue");
			string localizedString2 = GetLocalizedString(mostRight ? "Rightmost" : "Leftmost");
			string text = "";
			if (ActionValue == EffectsValues.NO_VALUE)
			{
				localizedString = localizedString.Replace("{1} ", "").Replace("{1}", "");
				localizedString = localizedString.Replace("{2}", "{1}");
				text = Smart.Format(localizedString, BattleAction.GetActionName(), localizedString2);
			}
			else
			{
				text = Smart.Format(localizedString, BattleAction.GetActionName(), ActionValue, localizedString2);
			}
			if (loseRune)
			{
				text = AppendLoseRuneLocalizedDescription(text);
			}
			return GetDescriptionWithSecondVirtueCheck(text);
		}
		if (newRuneType == NewRuneType.ReplaceSpecificRune)
		{
			string localizedString3 = GetLocalizedString("ReplaceSpecificVirtue");
			if (ActionValue == EffectsValues.NO_VALUE)
			{
				localizedString3 = localizedString3.Replace("{3} ", "").Replace("{3}", "");
				if (!enableSpecificRuneActionValue)
				{
					localizedString3 = localizedString3.Replace("{1} ", "").Replace("{1}", "");
					localizedString3 = localizedString3.Replace("{2}", "{1}");
					return GetDescriptionWithSecondVirtueCheck(Smart.Format(localizedString3, specificRuneBattleAction.GetActionName(), BattleAction.GetActionName()));
				}
				return GetDescriptionWithSecondVirtueCheck(Smart.Format(localizedString3, specificRuneBattleAction.GetActionName(), specificRuneActionValue, BattleAction.GetActionName()));
			}
			if (!enableSpecificRuneActionValue)
			{
				localizedString3 = localizedString3.Replace("{1} ", "").Replace("{1}", "");
				localizedString3 = localizedString3.Replace("{2}", "{1}");
				localizedString3 = localizedString3.Replace("{3}", "{2}");
				return GetDescriptionWithSecondVirtueCheck(Smart.Format(localizedString3, specificRuneBattleAction.GetActionName(), BattleAction.GetActionName(), ActionValue));
			}
			return GetDescriptionWithSecondVirtueCheck(Smart.Format(localizedString3, specificRuneBattleAction.GetActionName(), specificRuneActionValue, BattleAction.GetActionName(), ActionValue));
		}
		if (newRuneType == NewRuneType.ReplaceRune)
		{
			string localizedString4 = GetLocalizedString("ReplaceVirtue");
			string localizedString5 = GetLocalizedString(mostRight ? "Rightmost" : "Leftmost");
			string text2 = "";
			if (ActionValue == EffectsValues.NO_VALUE)
			{
				localizedString4 = localizedString4.Replace("{2}", "").Replace("{1} ", "{1}");
				text2 = Smart.Format(localizedString4, localizedString5, BattleAction.GetActionName());
			}
			else
			{
				text2 = Smart.Format(localizedString4, localizedString5, BattleAction.GetActionName(), ActionValue);
			}
			if (loseRune)
			{
				text2 = AppendLoseRuneLocalizedDescription(text2);
			}
			return GetDescriptionWithSecondVirtueCheck(text2);
		}
		if (newRuneType == NewRuneType.ReplaceAllRunes)
		{
			string localizedString6 = GetLocalizedString("ReplaceAllVirtues");
			if (ActionValue == EffectsValues.NO_VALUE)
			{
				localizedString6 = ((!LanguagesIndexes.IsCurrentLanguagePortuguese()) ? localizedString6.Replace("{1} ", "").Replace("{1}", "") : localizedString6.Replace(" {1}", ""));
				return GetDescriptionWithSecondVirtueCheck(Smart.Format(localizedString6, BattleAction.GetActionName()));
			}
			return GetDescriptionWithSecondVirtueCheck(Smart.Format(localizedString6, BattleAction.GetActionName(), ActionValue));
		}
		return "";
		string GetDescriptionWithSecondVirtueCheck(string description)
		{
			if (enableSecondVirtueChange)
			{
				return description + "\n" + secondVirtueChange.OmenConvertedDescription();
			}
			return description;
		}
	}

	private string GetLocalizedString(string id)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(id);
	}

	private string AppendLoseRuneLocalizedDescription(string description)
	{
		string localizedString = GetLocalizedString("LoseSpecificVirtue");
		string text = "";
		if (!enableSpecificRuneActionValue)
		{
			localizedString = localizedString.Replace("{0} ", "").Replace("{0}", "");
			localizedString = localizedString.Replace("{1}", "{0}");
			text = Smart.Format(localizedString, specificRuneBattleAction.GetActionName());
		}
		else
		{
			text = Smart.Format(localizedString, specificRuneBattleAction.GetActionName(), specificRuneActionValue);
		}
		return description = description + "\n" + text;
	}
}
